\begin{equation}
    \label{eq-inexact-halpern}
    \textrm{Find $\tilde{z}^k$ such that } \norm{G(z^k) - \tilde{z}^k}\leq \gamma_k,\; z^{k+1} = \beta_k z^0 + (1-\beta_k)z^k - \eta_k \tilde{z}^k,
    \tag{\textrm{iHI}}
\end{equation}

We use $\bb{X}$,  $\bb{Y}$ and $\bb{Z}$ to denote finite dimensional Euclidean spaces equipped with the standard inner product $\inprod{\cdot}{\cdot}$ and the induced Euclidean norm $\norm{\cdot}$. Moreover, we use $\|\cdot\|_\infty$ to denote the infinity norm. Let $n$ be a positive integer, the standard basis for $\bb{R}^n$ is denoted as $\{e_1,\dots, e_n\}$ and the vector of all ones in $\bb{R}^n$ is denoted as $\mathds{1}_n$. We use $\overline{\bb{R}}$ to represent the extended reals $\bb{R}\cup\{\pm\infty\}$. Let $f:\bb{X}\to\bb{R}$ be a differentiable function, its gradient at a point $x\in \bb{X}$ is denoted as $\nabla f(x)$. If $\bb{X} = \bb{R}$, i.e., $f$ is a univariate function, then its derivative is denoted as $f'$. If $f:\bb{X}\times\bb{Y}\to\bb{R}$ is a differentiable {function} of two vector variables, we use $\nabla_xf(x,y)$ and $\nabla_yf(x,y)$ to denote the partial derivatives with respect to $x\in \bb{X}$ and $y\in \bb{Y}$, respectively. In this way, the gradient of $f$ at the point $(x,y)$ is denoted as $\nabla f(x,y) = [\nabla_xf(x,y);\nabla_yf(x,y)]$, where $[\cdot;\dots;\cdot]$ is the column vector stacked from its components.


\textbf{Set-valued mappings.} Let $G:\bb{X}\rightrightarrows 2^\bb{X}$ be a set-valued mapping, we use $\dom{G}:=\left\{x\in \bb{X}:G(x)\neq \emptyset\right\}$ to denote its domain and use $\mathrm{graph}(G):=\left\{(x,x')\in \bb{X}\times \bb{X}: x'\in G(x)\right\}$ to denote its graph. Then the inverse of $G$ is denoted as $G^{-1}(x'):=\left\{x\in\bb{X}: x'\in G(x)\right\}$. We say that $G$ is single-valued if $G(x)$ is a singleton for any $x\in \bb{X}$.


\textbf{Resolvent operators.} For a monotone operator $G:\bb{X}\rightrightarrows 2^\bb{X}$, we denote its resolvent operator as $J_G:=(I+G)^{-1}$, where $I$ denotes the identity mapping. It is easy to verify that when $G$ is monotone, $J_G$ is single-valued with $\dom{G} = \bb{X}$. Note also that for a closed, proper and convex function $f:\bb{X}\to \overline{\bb{R}}$ and any positive scalar $\alpha\in \bb{R}$, it holds that $J_{\alpha \partial f}(x) = \prox{\alpha f}{x}$. In particular, for any closed convex set $\cal{C}\subseteq \bb{X}$ and any positive scalar $\alpha\in \bb{R}$, it holds that $J_{\alpha\partial\cal{I}_{\cal{C}}}(\cdot) = \proj{\cal{C}}{\cdot}$, i.e., the projection operator onto $\cal{C}$.


Let $G:\bb{X}\rightrightarrows 2^\bb{X}$ be a single-valued mapping, if there exists $L\geq 0$ such that
\[
    \left\lVert G(x_1) - G(x_2)\right\rVert \leq L\left\lVert x_1 - x_2\right\rVert,\quad \forall x_1,x_2\in \dom{G},
\]
then $G$ is said to be $L$-Lipschitz continuous. 

\textbf{Co-coerciveness.} Let $L > 0$. A set-valued mapping $G:\bb{X}\rightrightarrows 2^\bb{X}$ is said to be $\frac{1}{L}$-co-coercive if the following relation holds:
\[
    \left\langle G(x_1) - G(x_2), x_1 - x_2\right\rangle \geq \frac{1}{L}\left\lVert G(x_1) - G(x_2)\right\rVert^2,\quad \forall x_1,x_2\in \dom{G}.
\]


As mentioned in the introduction, in the ideal case when $G(z)$ can be evaluated exactly for any $z\in \bb{Z}$, the exact Halpern iterative scheme \eqref{eq-halpern} is guaranteed to possess an $O(k^{-1})$ rate. In this section, we illustrate that when the inexactness tolerance $\gamma_k$ satisfies some mild conditions, the inexact version \eqref{eq-inexact-halpern} shares a similar convergence rate. We assume for the rest of this paper that the problem \eqref{eq-inclusion-G} admits at least one solution.


In many modern applications in operation research and machine learning, $G$ usually admits a finite-sum structure. To see this, let $E:\bb{Z}\to 2^\bb{Z}$ and $F_i:\bb{Z}\to 2^\bb{Z}$, for $i = 1,\dots, N$, be maximal monotone operators. In addition, $F_i$ is assumed to be $\frac{1}{L_0}$-co-coercive for any $i = 1,\dots, N$. Then, many real-world applications can be reformulated as the following inclusion problem: 
\begin{equation}
	0\in E(z) + F(z):= E(z) + \frac{1}{N}\sum_{i = 1}^N F_i(z),\quad z\in \bb{Z},
	\label{eq-finitesum}	
\end{equation}

which is equivalent to the following new problem involving the resolvent operator of $E$:
\begin{equation}
	\label{eq-finitesum-G}
	0\in G(z):= \frac{1}{\alpha}\left(z - J_{\alpha E}\left(z -  \frac{\alpha}{N}\sum_{i = 1}^NF_i(z)\right)\right),\quad z\in \bb{Z}.
\end{equation}

However, when $N$ is large, which is typically the case in practical applications, evaluating the sum $ \frac{1}{N}\sum_{i = 1}^NF_i(z) $ can be costly. This motivates us to consider stochastic/randomized variants of the inexact Halpern fixed-point iterative scheme \eqref{eq-inexact-halpern}. Specifically, given $z^0\in \bb{Z}$, it is natural to consider performing the following steps for $k\geq 0$:
\begin{equation}
\label{eq-isHalpern}
\left\{
	\begin{aligned}
		&\; \textrm{Find a stochastic estimator $ \widetilde{F}(z^k) $ satisfying $ \bb{E}\left[\norm{F(z^k) - \widetilde{F}(z^k)}^2\right] \leq \frac{1}{2} \sigma_k^2 $}, \\ 
		&\; 	\textrm{Find $\bar{z}^k$ such that } \norm{J_{\alpha E}\left(z^k - \alpha \widetilde{F}(z^k) \right) - \bar{z}^k}\leq \frac{\sqrt{2}}{2}\alpha \gamma_k,\\
		&\; \tilde{z}^k = \frac{1}{\alpha}(z^k - \bar{z}^k), \quad  z^{k+1} = \beta_k z^0 + (1-\beta_k)z^k - \eta_k \tilde{z}^k, 
	\end{aligned}
	\right.
    \tag{\textrm{isHI}}
\end{equation}

where $ \alpha\in (0,4/L_0)$, $\beta_k = 1/(k+2)$, $\eta_k  = (1-\beta_k)/L$ with $L:= 4/(\alpha(4-\alpha L_0))$, $\gamma_k \geq 0$ and $\sigma_k\geq 0$ are chosen appropriately. Here, we use $\bb{E}$ to denote the expectation with respect to all the randomness at any iteration of \eqref{eq-isHalpern}.

