statement.raw_tex:
\begin{theorem}
	\label{thm-rate-ishi}
	Suppose that $G$ is $\frac{1}{L}$-co-coercive for a constant $L>0$. Let $\{z^k\}$ be the sequence generated by \eqref{eq-isHalpern} for solving \eqref{eq-finitesum-G}. Then it holds that 
	\begin{align}
		\bb{E}\left[\norm{G(z^k)}^2\right] \leq &\;  \frac{\left(7L\norm{z^0 - z^*} + 10\sqrt{\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2}\right)^2}{(k+1)(k+2)},\quad k\geq 0, \label{eq-thm-rate-ishi-G}	\\
		\bb{E}\left[\norm{z^{k+1} - z^k}^2\right] \leq &\; \frac{8\left(7L\norm{z^0 - z^*} + 11\sqrt{\sum_{i = 0}^{k}(i+1)^2(\sigma_i + \gamma_i)^2}\right)^2 }{L^2(k+1)(k+2)}, \quad k\geq 0,\label{eq-thm-rate-ishi-Z}
	\end{align}
	where $z^*$ is a solution such that $G(z^*) = 0$.
\end{theorem}

