\begin{theorem}
	\label{thm-rate-ishi}
	Suppose that $G$ is $\frac{1}{L}$-co-coercive for a constant $L>0$. Let $\{z^k\}$ be the sequence generated by \eqref{eq-isHalpern} for solving \eqref{eq-finitesum-G}. Then it holds that 
	\begin{align}
		\bb{E}\left[\norm{G(z^k)}^2\right] \leq &\;  \frac{\left(7L\norm{z^0 - z^*} + 10\sqrt{\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2}\right)^2}{(k+1)(k+2)},\quad k\geq 0, \label{eq-thm-rate-ishi-G}	\\
		\bb{E}\left[\norm{z^{k+1} - z^k}^2\right] \leq &\; \frac{8\left(7L\norm{z^0 - z^*} + 11\sqrt{\sum_{i = 0}^{k}(i+1)^2(\sigma_i + \gamma_i)^2}\right)^2 }{L^2(k+1)(k+2)}, \quad k\geq 0,\label{eq-thm-rate-ishi-Z}
	\end{align}
	where $z^*$ is a solution such that $G(z^*) = 0$.
\end{theorem}

\begin{proof}
	We recall from Lemma \ref{lemma-key-estimate} that 
	\[
		\mathcal{L}_{k+1} \leq \mathcal{L}_k  + \frac{1}{12L}\norm{G(z^k)}^2 + \frac{4(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2,\quad k\geq 0.
	\]
	Taking the full expectation $\bb{E}$ (with respect to all the randomness) on both side of the above inequality yields 
	\[
		\bb{E}[\mathcal{L}_{k+1}] \leq \bb{E}[\mathcal{L}_k]  + \frac{1}{12L}\bb{E}\left[\norm{G(z^k)}^2\right] + \frac{4(k+1)^2}{L}(\sigma_k + \gamma_k)^2,\quad k\geq 0,
	\]
	where the third term is due to Lemma \ref{lemma-exp-error}. Then, by recursively applying the above and summing up the resulted inequalities gives:
	\begin{equation}\label{eq-thm-ishi-1}
	\bb{E}[\mathcal{L}_k] \leq \frac{1}{12L}\sum_{i = 0}^{k-1}\bb{E}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 1}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,\quad k\geq 0.	
	\end{equation}
	Here, the case when $k= 0$ holds trivially since $\mathcal{L}_0 = 0$. By the definition of the potential function $\mathcal{L}_k$ 
	we see that 
	\begin{equation}
	\label{eq-thm-ishi-2}
		\bb{E}[\mathcal{L}_k] = \frac{k(k+1)}{2L}\bb{E}\left[\norm{G(z^k)}^2\right] - (k+1)\bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right],\quad k\geq 0.	
	\end{equation}
	Moreover, let $z^*$ be any solution such that $G(z^*) = 0$, since 
	\begin{align*}
	    \bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right] = &\; \bb{E}\left[\inprod{G(z^k)}{z^0 - z^*}\right] + \bb{E}\left[\inprod{G(z^k)}{z^* - z^k}\right] \\
        \leq &\;  \bb{E}\left[\inprod{G(z^k)}{z^0 - z^*}\right],
	\end{align*}
	it holds that 
	\begin{equation}
	\label{eq-thm-ishi-3}
		\bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right] \leq \bb{E}\left[\norm{G(z^k)}\norm{z^0 - z^*}\right] = \norm{z^0 - z^*}\bb{E}\left[\norm{G(z^k)}\right].	
	\end{equation}
	Combining \eqref{eq-thm-ishi-1}, \eqref{eq-thm-ishi-2} and \eqref{eq-thm-ishi-3}, we get
	\begin{equation*}
	% \label{eq-thm-ishi-4}
		\begin{aligned}
			&\; \bb{E}\left[\norm{G(z^k)}^2 \right] \\
			\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\bb{E}\left[\norm{G(z^i)}^2\right] + \frac{2L}{k}\norm{z^0 - z^*}\bb{E}\left[\norm{G(z^k)}\right] + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2 \\
			\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\bb{E}\left[\norm{G(z^i)}^2\right] + \frac{2L}{k}\norm{z^0 - z^*}\left(\bb{E}\left[\norm{G(z^k)}^2\right]\right)^{\frac{1}{2}} \\
   &\; + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,
		\end{aligned}
	\end{equation*}
	for all $ k\geq 1 $. Now denote 
	\[
		a_k:= \left(\bb{E}\left[\norm{G(z^k)}^2\right]\right)^{\frac{1}{2}}, \quad k\geq 0, \quad b_k:= \sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,\quad k\geq 1,\quad D:= L\norm{z^0 - z^*}.
	\]
	Similar to \eqref{thm-rate-proof-2}, we can derive 
	\[
		a_k^2 \leq \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)}.
	\]
	Then, by following the proof of Theorem \ref{thm-convergence-rate} directly, we see that 
	\[
		a_k^2\leq \frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)}, \quad k\geq 1,
	\]
	which proves \eqref{eq-thm-rate-ishi-G} since the case for $k = 0$ is trivial. Moreover, we can also verify that
		\begin{align*}
		    \bb{E}\left[\norm{\tilde{z}^k}^2\right] \leq &\;  2\bb{E}\left[\norm{G(z^k)}^2 + \norm{\tilde{z}^k - G(z^k)}^2\right] \\
      \leq &\; 2a_k^2 + 2(\sigma_k + \gamma_k)^2 \\
      \leq  &\; \frac{2(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)} + 2(\sigma_k + \gamma_k)^2.
		\end{align*}
	Then, by following the proof of Theorem \ref{thm-convergence-rate} again, we can show that 
	\[
		a_k^2\leq \frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)},\quad \bb{E}\left[\norm{z^{k+1} - z^k}^2\right] \leq \frac{8(7D + 11\sqrt{b_{k+1}})^2 }{L^2(k+1)(k+2)},\quad k\geq 0,
	\]
	which is exactly \eqref{eq-thm-rate-ishi-Z}. Hence, the proof is completed.
\end{proof}

\begin{equation}
    \label{eq-inexact-halpern}
    \textrm{Find $\tilde{z}^k$ such that } \norm{G(z^k) - \tilde{z}^k}\leq \gamma_k,\; z^{k+1} = \beta_k z^0 + (1-\beta_k)z^k - \eta_k \tilde{z}^k,
    \tag{\textrm{iHI}}
\end{equation}

In many modern applications in operation research and machine learning, $G$ usually admits a finite-sum structure. To see this, let $E:\bb{Z}\to 2^\bb{Z}$ and $F_i:\bb{Z}\to 2^\bb{Z}$, for $i = 1,\dots, N$, be maximal monotone operators. In addition, $F_i$ is assumed to be $\frac{1}{L_0}$-co-coercive for any $i = 1,\dots, N$. Then, many real-world applications can be reformulated as the following inclusion problem: 
\begin{equation}
	0\in E(z) + F(z):= E(z) + \frac{1}{N}\sum_{i = 1}^N F_i(z),\quad z\in \bb{Z},
	\label{eq-finitesum}	
\end{equation}

which is equivalent to the following new problem involving the resolvent operator of $E$:
\begin{equation}
	\label{eq-finitesum-G}
	0\in G(z):= \frac{1}{\alpha}\left(z - J_{\alpha E}\left(z -  \frac{\alpha}{N}\sum_{i = 1}^NF_i(z)\right)\right),\quad z\in \bb{Z}.
\end{equation}

However, when $N$ is large, which is typically the case in practical applications, evaluating the sum $ \frac{1}{N}\sum_{i = 1}^NF_i(z) $ can be costly. This motivates us to consider stochastic/randomized variants of the inexact Halpern fixed-point iterative scheme \eqref{eq-inexact-halpern}. Specifically, given $z^0\in \bb{Z}$, it is natural to consider performing the following steps for $k\geq 0$:
\begin{equation}
\label{eq-isHalpern}
\left\{
	\begin{aligned}
		&\; \textrm{Find a stochastic estimator $ \widetilde{F}(z^k) $ satisfying $ \bb{E}\left[\norm{F(z^k) - \widetilde{F}(z^k)}^2\right] \leq \frac{1}{2} \sigma_k^2 $}, \\ 
		&\; 	\textrm{Find $\bar{z}^k$ such that } \norm{J_{\alpha E}\left(z^k - \alpha \widetilde{F}(z^k) \right) - \bar{z}^k}\leq \frac{\sqrt{2}}{2}\alpha \gamma_k,\\
		&\; \tilde{z}^k = \frac{1}{\alpha}(z^k - \bar{z}^k), \quad  z^{k+1} = \beta_k z^0 + (1-\beta_k)z^k - \eta_k \tilde{z}^k, 
	\end{aligned}
	\right.
    \tag{\textrm{isHI}}
\end{equation}

\begin{lemma}
    \label{lemma-zdiff}
    Let $\{z^k\}$ be generated by \eqref{eq-inexact-halpern} with $\eta_k = (1-\beta_k)/L$, then the following expressions for $z^{k+1} - z^k$ for $k\geq 0$ hold:
    \begin{enumerate}
        \item $z^{k+1} - z^k = \beta_k(z^0 - z^k) - \frac{1-\beta_k}{L}\tilde{z}^k$;
        \item $z^{k+1} - z^k = \frac{\beta_k}{1-\beta_k}(z^0 - z^{k+1}) - \frac{1}{L}\tilde{z}^k$;
        \item $z^{k+1} - z^k = -\frac{1-\beta_k}{L}\tilde{z}^k + \sum_{i = 0}^{k-1}\frac{\beta_k}{L}\left( \prod_{j = i}^{k-1} (1-\beta_j)\right) \tilde{z}^i$, for $k\geq 0$. Moreover, if $\beta_k:= 1/(k+2)$, it holds that 
    \begin{equation}
        \label{eq-lemma-zdiff-1}
        \begin{aligned}
            &\; \norm{z^{k+1} - z^k}^2 \\
            \leq &\; \left\{
            \begin{array}{ll}
                \frac{1}{4L^2} \norm{\tilde{z}^0}^2, & \textrm{if } k = 0,\\[5pt]
                \frac{2(k+1)^2}{L^2(k+2)^2}\norm{\tilde{z}^k}^2 + \frac{2k}{L^2(k+1)^2(k+2)^2}\sum_{i = 0}^{k-1}(i+1)^2\norm{\tilde{z}^i}^2,    & \textrm{if } k\geq 1. 
            \end{array}
        \right.
        \end{aligned}
    \end{equation}
    \end{enumerate}
\end{lemma}

\begin{lemma}
    \label{lemma-key-estimate}
    Let $\{z^k\}$ be generated by \eqref{eq-inexact-halpern} with $\eta_k = (1-\beta_k)/L$, then for $k\geq 0$, it holds that 
    \begin{equation}
        \label{eq-lemma-key-estimate-1}
        \begin{aligned}
            &\; \frac{1}{2L}\norm{G(z^{k+1})}^2 - \frac{\beta_k}{1-\beta_k}\inprod{G(z^{k+1})}{z^0 - z^{k+1}} \\ \leq &\;   \frac{1 - 2\beta_k}{2L}\norm{G(z^k)}^2 - \beta_k\inprod{G(z^k)}{z^0 - z^k} + \frac{\beta_k}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k}\\
            &\; + \frac{1}{2L}\norm{G(z^k) - \tilde{z}^k}^2.
        \end{aligned}
    \end{equation}
    In particular, if $\beta_k:=1/(k+2)$, then for $k\geq 0$,
    \begin{equation}
        \label{eq-lemma-key-estimate-2}
        \mathcal{L}_{k+1} \leq \mathcal{L}_k  + \frac{1}{12L}\norm{G(z^k)}^2 + \frac{4(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2,
    \end{equation}
    where $\mathcal{L}_k$ is the potential function that is defined as 
    \[
        \mathcal{L}_k:= \frac{k(k+1)}{2L}\norm{G(z^k)}^2 - (k+1)\inprod{G(z^k)}{z^0 - z^k},\quad \forall k\geq 0.
    \]
\end{lemma}

\begin{proof}
    By the co-coerciveness of the mapping $G$, we see that 
    \[
        \frac{1}{L}\norm{G(z^{k+1}) - G(z^k)}^2 \leq \inprod{G(z^{k+1}) - G(z^k)}{z^{k+1} - z^k},
    \]  
    which implies that 
    \begin{equation}
        \label{eq-lemma-key-estimate-3}
        \begin{aligned}
            &\; \frac{1}{2L}\norm{G(z^{k+1})}^2 + \frac{1}{2L}\norm{G(z^{k})}^2 +  \frac{1}{2L}\norm{G(z^{k+1}) - G(z^k)}^2 \\
            \leq &\;  \inprod{G(z^{k+1})}{z^{k+1} - z^k + \frac{1}{L}G(z^k)} - \inprod{G(z^k)}{z^{k+1} - z^k}.
        \end{aligned}
    \end{equation}
    The first two expressions for $z^{k+1} - z^k$ in Lemma \ref{lemma-zdiff} together with \eqref{eq-lemma-key-estimate-3} and the Cauchy-Schwarz inequality imply that 
        \begin{align*}
            &\; \frac{1}{2L}\norm{G(z^{k+1})}^2 + \frac{1}{2L}\norm{G(z^{k})}^2 +  \frac{1}{2L}\norm{G(z^{k+1}) - G(z^k)}^2 \\
            \leq &\; \inprod{G(z^{k+1})}{\frac{\beta_k}{1-\beta_k}(z^0 - z^{k+1}) - \frac{1}{L}\tilde{z}^k + \frac{1}{L}G(z^k)} - \inprod{G(z^k)}{\beta_k(z^0 - z^k) - \frac{1-\beta_k}{L}\tilde{z}^k} \\
            = &\; \frac{\beta_k}{1-\beta_k}\inprod{G(z^{k+1})}{z^0 - z^{k+1}} - \beta_k\inprod{G(z^k)}{z^0 - z^k} + \frac{1}{L}\inprod{G(z^{k+1})}{G(z^k) - \tilde{z}^k} \\
            &\; + \frac{1-\beta_k}{L}\inprod{G(z^k)}{\tilde{z}^k}\\
            = &\; \frac{\beta_k}{1-\beta_k}\inprod{G(z^{k+1})}{z^0 - z^{k+1}} - \beta_k\inprod{G(z^k)}{z^0 - z^k}  + \frac{1}{L}\norm{G(z^k)}^2 \\
            &\; + \frac{1}{L}\inprod{G(z^{k+1}) - G(z^k)}{G(z^k) - \tilde{z}^k} - \frac{\beta_k}{L}\inprod{G(z^k)}{\tilde{z}^k} \\
            \leq &\; \frac{\beta_k}{1-\beta_k}\inprod{G(z^{k+1})}{z^0 - z^{k+1}} - \beta_k\inprod{G(z^k)}{z^0 - z^k}  + \frac{1 - \beta_k}{L}\norm{G(z^k)}^2 \\
            &\; + \frac{1}{2L}\norm{G(z^{k+1}) - G(z^k)}^2 + \frac{1}{2L}\norm{G(z^k) - \tilde{z}^k}^2 + \frac{\beta_k}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k}.
        \end{align*}
    Therefore, the inequality \eqref{eq-lemma-key-estimate-1} holds by rearranging terms in the above inequality. By substituting $ \beta_k:= 1 / (k+2) $ into \eqref{eq-lemma-key-estimate-1}, and using the Cauchy-Schwarz inequality and the definition of the potential function $ \mathcal{L}_k $, for $k\geq 0$, we see that 
    	\begin{align*}
    		\mathcal{L}_{k+1} \leq &\;  \mathcal{L}_k  + \frac{k+1}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k} + \frac{(k+1)(k+2)}{2L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		\leq &\; \mathcal{L}_k  + \frac{k+1}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k} + \frac{(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		\leq &\; \mathcal{L}_k  + \frac{k+1}{2L}\left(\frac{1}{6(k+1)}\norm{G(z^k)}^2 + 6(k+1) \norm{G(z^k) - \tilde{z}^k}^2 \right) \\
            &\; + \frac{(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		= &\; \mathcal{L}_k  + \frac{1}{12L}\norm{G(z^k)}^2 + \frac{4(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2,
    	\end{align*}
    which proves the inequality \eqref{eq-lemma-key-estimate-2}. Therefore, the proof is completed.
\end{proof}

\begin{lemma}
	\label{lemma-exp-error}
	Let $\{z^k\}$ be the sequence generated by \eqref{eq-isHalpern}, then it holds that
	\[
		\bb{E} \left[\norm{G(z^k) - \tilde{z}^k}^2\right] \leq \gamma_k + \sigma_k,\quad \forall k\geq 0.
	\]
\end{lemma}

\begin{theorem}
	\label{thm-convergence-rate}
	Suppose that $G$ is $\frac{1}{L}$-co-coercive for a constant $L>0$. Let $\{z^k\}$ be generated by \eqref{eq-inexact-halpern} with $\beta_k = 1/(k+2)$ and $\eta_k = (1-\beta_k)/L$, then it holds that
	\begin{align}
		\norm{G(z^k)}^2 \leq &\;  \frac{\left(7L\norm{z^0 - z^*} + 10\sqrt{\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2}\right)^2}{(k+1)(k+2)},\quad k\geq 0, \label{thm-rate-1}\\
		\norm{z^{k+1} - z^k}^2 \leq &\; \frac{8\left(7L\norm{z^0 - z^*} + 11\sqrt{\sum_{i = 0}^{k}(i+1)^2\gamma_i^2}\right)^2 }{L^2(k+1)(k+2)}, \quad k\geq 0,\label{thm-rate-2}
	\end{align}
	where $z^* \in \bb{Z}$ is any solution such that $G(z^*) = 0$.
\end{theorem}

\begin{proof}
	From Lemma \ref{lemma-key-estimate} and notice that $\mathcal{L}_0 = 0$, we can see that  
	\[
		\mathcal{L}_k \leq \frac{1}{12L}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2, \quad k\geq 1.
	\]
	By the definition of the potential function $\mathcal{L}_k$, we can see that 
		\begin{align*}
			\frac{k(k+1)}{2L}\norm{G(z^k)}^2 \leq &\; \frac{1}{12L}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + (k+1)\inprod{G(z^k)}{z^0 - z^k} \\
			\leq &\; \frac{1}{12L}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + (k+1)\norm{G(z^k)}\norm{z^0 - z^*}
		\end{align*} 
	where the last inequality is due to the fact that 
	\begin{align*}
	    \inprod{G(z^k)}{z^0 - z^k} = &\; \inprod{G(z^k)}{z^0 - z^*} + \inprod{G(z^k)}{z^* - z^k} \\
     \leq &\;  \inprod{G(z^k)}{z^0 - z^*} \\
     \leq &\;  \norm{G(z^k)}\norm{z^0 - z^*},
	\end{align*}
	and $z^*$ is any solution such that $G(z^*) = 0$.
 The first inequality holds, since $G$ is co-coercive. As a consequence, it holds that 
	\begin{equation}
	\label{thm-rate-proof-1}
		\norm{G(z^k)}^2 \leq \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + \frac{2L}{k}\norm{G(z^k)}\norm{z^0 - z^*},  
	\end{equation}
	for $k\geq 1$. For notational simplicity, let us denote 
	\[
		a_k:= \norm{G(z^k)}, \quad k\geq 0, \quad b_k:= \sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2,\quad k\geq 1,\quad D:= L\norm{z^0 - z^*}.
	\]
	Then, from \eqref{thm-rate-proof-1}, we see that, for $k\geq 1$, 
	\begin{align*}
		a_k^2 \leq &\;  \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{8}{k(k+1)}b_k + \frac{2D}{k}a_k \\
		\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{8}{k(k+1)}b_k + \frac{1}{2}\left(\frac{4D^2}{k^2} + a_k^2 \right),
	\end{align*}
	which implies that, for $k\geq 1$,
	\begin{equation}
	\label{thm-rate-proof-2}
	\begin{aligned}
	    a_k^2 \leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{16}{k(k+1)}b_k + \frac{4D^2}{k^2} \\
     \leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)}.
	\end{aligned}
	\end{equation}
	We next claim that the following inequality holds:
	\begin{equation}
		\label{thm-rate-proof-3}
		a_k^2 \leq \frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)},\quad k\geq 1.
	\end{equation}
	We shall prove the above claim by induction. First, from \eqref{thm-rate-proof-2} and notice that $a_0 \leq D$ by the $L$-Lipschitz continuity of $G$, we see that
	\[
		a_1^2 \leq \frac{1}{6}a_0^2 + 8b_1 + 4D^2 \leq  \frac{1}{6}D^2 + 8b_1 + 4D^2 \leq \frac{1}{6}(7D+10\sqrt{b_1})^2.
	\]
	So \eqref{thm-rate-proof-3} holds for $k = 1$. Suppose now that \eqref{thm-rate-proof-3} holds for indices $\{1,\dots, k-1\}$. Again, from \eqref{thm-rate-proof-2} and the fact that $b_k$ is non-decreasing, we deduce that 
		\begin{align*}
			a_k^2 \leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)} \\
			\leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} \frac{(7D + 10\sqrt{b_i})^2}{(i+1)(i+2)} + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)} \\
			\leq &\; \frac{(7D + 10\sqrt{b_k})^2}{3k(k+1)}\sum_{i = 0}^{k-1} \frac{1}{(i+1)(i+2)} + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)} \\
			= &\; \frac{(7D + 10\sqrt{b_k})^2}{3(k+1)^2} + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)} \\
			\leq &\; \frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)},
		\end{align*}
	which shows that \eqref{thm-rate-proof-3} holds for index $k$. Thus, by induction, \eqref{thm-rate-proof-3} holds for all $k\geq 1$. Moreover, it is clear that \eqref{thm-rate-proof-3} trivially holds for $k = 0$. This proves \eqref{thm-rate-1}.

	To prove  \eqref{thm-rate-2}, we first observe that 
	\[
		\norm{\tilde{z}^k}^2 \leq 2\norm{G(z^k)}^2 + 2\norm{G(z^k) - \tilde{z}^k}^2 \leq 2a_k^2 + 2\gamma_k^2 \leq  \frac{2(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)} + 2\gamma_k^2,\quad k\geq 0.
	\]
	Then, by the third statement of Lemma \ref{lemma-zdiff} and the fact that $b_k$ is non-decreasing, we see that for $k\geq 0$, 
		\begin{align*}
			\norm{z^{k+1} - z^k}^2
			\leq &\; \frac{2(k+1)^2}{L^2(k+2)^2}\norm{\tilde{z}^k}^2 + \frac{2k}{L^2(k+1)^2(k+2)^2}\sum_{i = 0}^{k-1}(i+1)^2\norm{\tilde{z}^i}^2 \\
			% \leq &\;  \frac{4(k+1)^2}{L^2(k+2)^2}\left(\frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)} + \gamma_k^2 \right) \\
   % &\; + \frac{4k}{L^2(k+1)^2(k+2)^2}\sum_{i = 0}^{k-1}\left(\frac{(i+1)(7D + 10\sqrt{b_i})^2}{i+2} + (i+1)^2 \gamma_i^2 \right) \\
			\leq &\;  \frac{4(k+1)^2}{L^2(k+2)^2}\left(\frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)} + \gamma_k^2 \right) \\
   &\; + \frac{4k}{L^2(k+1)^2(k+2)^2}\sum_{i = 0}^{k-1}\left(\frac{(i+1)(7D + 10\sqrt{b_k})^2}{i+2} + (i+1)^2 \gamma_i^2 \right) \\
			\leq &\; \frac{4(7D + 10\sqrt{b_k})^2}{L^2}\left(\frac{k+1}{(k+2)^3} + \frac{k^2}{(k+1)^2(k+2)^2}\right) \\
   &\; + \frac{4(k+1)^2}{L^2(k+2)^2}\gamma_k^2 + \frac{4k}{L^2(k+1)^2(k+2)^2}b_k \\
			\leq &\; \frac{8(7D + 10\sqrt{b_{k+1}})^2 + 8b_{k+1}}{L^2(k+1)(k+2)}\\
			\leq &\; \frac{8(7D + 11\sqrt{b_{k+1}})^2 }{L^2(k+1)(k+2)},
		\end{align*}
	which proves \eqref{thm-rate-2}. Therefore, the proof is completed.
\end{proof}

\begin{equation}\label{eq-thm-ishi-1}
\bb{E}[\mathcal{L}_k] \leq \frac{1}{12L}\sum_{i = 0}^{k-1}\bb{E}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 1}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,\quad k\geq 0.	
\end{equation}
Here, the case when $k= 0$ holds trivially since $\mathcal{L}_0 = 0$. By the definition of the potential function $\mathcal{L}_k$ 
we see that 
\begin{equation}
\label{eq-thm-ishi-2}
	\bb{E}[\mathcal{L}_k] = \frac{k(k+1)}{2L}\bb{E}\left[\norm{G(z^k)}^2\right] - (k+1)\bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right],\quad k\geq 0.	
\end{equation}

	Moreover, let $z^*$ be any solution such that $G(z^*) = 0$, since 
	\begin{align*}
	    \bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right] = &\; \bb{E}\left[\inprod{G(z^k)}{z^0 - z^*}\right] + \bb{E}\left[\inprod{G(z^k)}{z^* - z^k}\right] \\
        \leq &\;  \bb{E}\left[\inprod{G(z^k)}{z^0 - z^*}\right],
	\end{align*}
	it holds that 
	\begin{equation}
	\label{eq-thm-ishi-3}
		\bb{E}\left[\inprod{G(z^k)}{z^0 - z^k}\right] \leq \bb{E}\left[\norm{G(z^k)}\norm{z^0 - z^*}\right] = \norm{z^0 - z^*}\bb{E}\left[\norm{G(z^k)}\right].	
	\end{equation}

	Combining \eqref{eq-thm-ishi-1}, \eqref{eq-thm-ishi-2} and \eqref{eq-thm-ishi-3}, we get
	\begin{equation*}
	% \label{eq-thm-ishi-4}
		\begin{aligned}
			&\; \bb{E}\left[\norm{G(z^k)}^2 \right] \\
			\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\bb{E}\left[\norm{G(z^i)}^2\right] + \frac{2L}{k}\norm{z^0 - z^*}\bb{E}\left[\norm{G(z^k)}\right] + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2 \\
			\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\bb{E}\left[\norm{G(z^i)}^2\right] + \frac{2L}{k}\norm{z^0 - z^*}\left(\bb{E}\left[\norm{G(z^k)}^2\right]\right)^{\frac{1}{2}} \\
   &\; + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,
		\end{aligned}
	\end{equation*}
	for all $ k\geq 1 $. Now denote 
	\[
		a_k:= \left(\bb{E}\left[\norm{G(z^k)}^2\right]\right)^{\frac{1}{2}}, \quad k\geq 0, \quad b_k:= \sum_{i = 0}^{k-1}(i+1)^2(\sigma_i + \gamma_i)^2,\quad k\geq 1,\quad D:= L\norm{z^0 - z^*}.
	\]

		\begin{align*}
		    \bb{E}\left[\norm{\tilde{z}^k}^2\right] \leq &\;  2\bb{E}\left[\norm{G(z^k)}^2 + \norm{\tilde{z}^k - G(z^k)}^2\right] \\
      \leq &\; 2a_k^2 + 2(\sigma_k + \gamma_k)^2 \\
      \leq  &\; \frac{2(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)} + 2(\sigma_k + \gamma_k)^2.
		\end{align*}

For $k\geq 1$, substituting $\beta_k = 1/(k+2)$ into the  expression of $z^{k+1} - z^k$ in the third statement yields that 
\begin{align*}
    z^{k+1} - z^k = &\; -\frac{k+1}{L(k+2)}\tilde{z}^k + \sum_{i = 0}^{k-1}\frac{1}{L(k+2)}\left( \prod_{j = i}^{k-1} \frac{j+1}{j+2}\right) \tilde{z}^i \\
    =&\;  -\frac{k+1}{L(k+2)}\tilde{z}^k + \sum_{i = 0}^{k-1}\frac{i+1}{L(k+1)(k+2)}\tilde{z}^i.
\end{align*}

    Therefore, by applying the Cauchy-Schwarz inequality twice, we see that 
        \begin{align*}
            \norm{z^{k+1} - z^k}^2 = &\; \norm{-\frac{k+1}{L(k+2)}\tilde{z}^k + \sum_{i = 0}^{k-1}\frac{i+1}{L(k+1)(k+2)}\tilde{z}^i}^2 \\
            \leq &\; \frac{2(k+1)^2}{L^2(k+2)^2}\norm{\tilde{z}^k}^2 + \frac{2}{L^2(k+1)^2(k+2)^2}\norm{\sum_{i = 0}^{k-1}(i+1)\tilde{z}^i}^2 \\
            \leq &\; \frac{2(k+1)^2}{L^2(k+2)^2}\norm{\tilde{z}^k}^2 + \frac{2k}{L^2(k+1)^2(k+2)^2}\sum_{i = 0}^{k-1}(i+1)^2\norm{\tilde{z}^i}^2,
        \end{align*}    
    which proves \eqref{eq-lemma-zdiff-1}. Hence, the proof is completed.
\end{proof}

\begin{proof}
    By the co-coerciveness of the mapping $G$, we see that 
    \[
        \frac{1}{L}\norm{G(z^{k+1}) - G(z^k)}^2 \leq \inprod{G(z^{k+1}) - G(z^k)}{z^{k+1} - z^k},
    \]  
    which implies that 
    \begin{equation}
        \label{eq-lemma-key-estimate-3}
        \begin{aligned}
            &\; \frac{1}{2L}\norm{G(z^{k+1})}^2 + \frac{1}{2L}\norm{G(z^{k})}^2 +  \frac{1}{2L}\norm{G(z^{k+1}) - G(z^k)}^2 \\
            \leq &\;  \inprod{G(z^{k+1})}{z^{k+1} - z^k + \frac{1}{L}G(z^k)} - \inprod{G(z^k)}{z^{k+1} - z^k}.
        \end{aligned}
    \end{equation}

    Therefore, the inequality \eqref{eq-lemma-key-estimate-1} holds by rearranging terms in the above inequality. By substituting $ \beta_k:= 1 / (k+2) $ into \eqref{eq-lemma-key-estimate-1}, and using the Cauchy-Schwarz inequality and the definition of the potential function $ \mathcal{L}_k $, for $k\geq 0$, we see that 
    	\begin{align*}
    		\mathcal{L}_{k+1} \leq &\;  \mathcal{L}_k  + \frac{k+1}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k} + \frac{(k+1)(k+2)}{2L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		\leq &\; \mathcal{L}_k  + \frac{k+1}{L}\inprod{G(z^k)}{G(z^k) - \tilde{z}^k} + \frac{(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		\leq &\; \mathcal{L}_k  + \frac{k+1}{2L}\left(\frac{1}{6(k+1)}\norm{G(z^k)}^2 + 6(k+1) \norm{G(z^k) - \tilde{z}^k}^2 \right) \\
            &\; + \frac{(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2 \\
    		= &\; \mathcal{L}_k  + \frac{1}{12L}\norm{G(z^k)}^2 + \frac{4(k+1)^2}{L}\norm{G(z^k) - \tilde{z}^k}^2,
    	\end{align*}
    which proves the inequality \eqref{eq-lemma-key-estimate-2}. Therefore, the proof is completed.
\end{proof}

\begin{proof}
	Since the resolvent operator $J_{\alpha E}$ is firmly non-expansive (hence $1$-Lipschitz continuous), we see that 
		\begin{align*}
			&\; \norm{G(z^k) - \tilde{z}^k}^2 \\
			= &\; \norm{\frac{1}{\alpha}\left(z^k - J_{\alpha E}\left(z^k -  \alpha F(z^k)\right)\right)- \tilde{z}^k}^2 \\
			= &\; \frac{1}{\alpha^2}\norm{J_{\alpha E}\left(z^k -  \alpha F(z^k)\right) - \bar{z}^k}^2 \\
			\leq &\; \frac{2}{\alpha^2}\norm{J_{\alpha E}\left(z^k -  \alpha F(z^k)\right) - J_{\alpha E}\left(z^k -  \alpha \widetilde{F}(z^k)\right)}^2 + \frac{2}{\alpha^2}\norm{J_{\alpha E}\left(z^k - \alpha \widetilde{F}(z^k)\right) - \bar{z}^k}^2 \\
			\leq &\; 2\norm{F(z^k) - \widetilde{F}(z^k)}^2 + \gamma_k,
		\end{align*}
    where the first equality uses the definition of $G$ and the second equality uses the fact that $\tilde z^k = \frac{1}{\alpha}(z^k - \bar{z}^k)$, and the first inequality is due to the Cauchy-Schwarz inequality.

	By the definition of the potential function $\mathcal{L}_k$, we can see that 
		\begin{align*}
			\frac{k(k+1)}{2L}\norm{G(z^k)}^2 \leq &\; \frac{1}{12L}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + (k+1)\inprod{G(z^k)}{z^0 - z^k} \\
			\leq &\; \frac{1}{12L}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{4}{L}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + (k+1)\norm{G(z^k)}\norm{z^0 - z^*}
		\end{align*} 
	where the last inequality is due to the fact that 
	\begin{align*}
	    \inprod{G(z^k)}{z^0 - z^k} = &\; \inprod{G(z^k)}{z^0 - z^*} + \inprod{G(z^k)}{z^* - z^k} \\
     \leq &\;  \inprod{G(z^k)}{z^0 - z^*} \\
     \leq &\;  \norm{G(z^k)}\norm{z^0 - z^*},
	\end{align*}
	and $z^*$ is any solution such that $G(z^*) = 0$.
 The first inequality holds, since $G$ is co-coercive. As a consequence, it holds that 
	\begin{equation}
	\label{thm-rate-proof-1}
		\norm{G(z^k)}^2 \leq \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1}\norm{G(z^i)}^2 + \frac{8}{k(k+1)}\sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2 + \frac{2L}{k}\norm{G(z^k)}\norm{z^0 - z^*},  
	\end{equation}

	for $k\geq 1$. For notational simplicity, let us denote 
	\[
		a_k:= \norm{G(z^k)}, \quad k\geq 0, \quad b_k:= \sum_{i = 0}^{k-1}(i+1)^2\gamma_i^2,\quad k\geq 1,\quad D:= L\norm{z^0 - z^*}.
	\]
	Then, from \eqref{thm-rate-proof-1}, we see that, for $k\geq 1$, 
	\begin{align*}
		a_k^2 \leq &\;  \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{8}{k(k+1)}b_k + \frac{2D}{k}a_k \\
		\leq &\; \frac{1}{6k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{8}{k(k+1)}b_k + \frac{1}{2}\left(\frac{4D^2}{k^2} + a_k^2 \right),
	\end{align*}
	which implies that, for $k\geq 1$,
	\begin{equation}
	\label{thm-rate-proof-2}
	\begin{aligned}
	    a_k^2 \leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{16}{k(k+1)}b_k + \frac{4D^2}{k^2} \\
     \leq &\; \frac{1}{3k(k+1)}\sum_{i = 0}^{k-1} a_i^2 + \frac{48}{(k+1)(k+2)}b_k + \frac{24D^2}{(k+1)(k+2)}.
	\end{aligned}
	\end{equation}

We next claim that the following inequality holds:
\begin{equation}
	\label{thm-rate-proof-3}
	a_k^2 \leq \frac{(7D + 10\sqrt{b_k})^2}{(k+1)(k+2)},\quad k\geq 1.
\end{equation}
We shall prove the above claim by induction. First, from \eqref{thm-rate-proof-2} and notice that $a_0 \leq D$ by the $L$-Lipschitz continuity of $G$, we see that
\[
	a_1^2 \leq \frac{1}{6}a_0^2 + 8b_1 + 4D^2 \leq  \frac{1}{6}D^2 + 8b_1 + 4D^2 \leq \frac{1}{6}(7D+10\sqrt{b_1})^2.
\]
